import { Dialog, DialogContent, DialogTitle, Typography } from '@mui/material';
import { useTranslation } from 'react-i18next';
import Form from '../../components/form';
import * as Yup from 'yup';
import { IField } from '../../type';
import {
  formatSelect,
  getHoursAndMinutesAndSeconds
} from '../../../../utils/formatters';
import { useDispatch } from '../../../../store';
import { createLabor, editLabor } from '../../../../slices/labor';
import useAuth from '../../../../hooks/useAuth';
import FeatureErrorMessage from '../../components/FeatureErrorMessage';
import { PlanFeature } from '../../../../models/owns/subscriptionPlan';
import { getErrorMessage } from '../../../../utils/api';
import { useContext } from 'react';
import { CustomSnackBarContext } from '../../../../contexts/CustomSnackBarContext';
import Labor from '../../../../models/owns/labor';

interface AddTimeProps {
  open: boolean;
  onClose: () => void;
  workOrderId: number;
  labor?: Labor;
}

export default function AddTimeModal({
  open,
  onClose,
  workOrderId,
  labor
}: AddTimeProps) {
  const { t }: { t: any } = useTranslation();
  const dispatch = useDispatch();
  const { hasFeature } = useAuth();
  const { showSnackBar } = useContext(CustomSnackBarContext);
  const isEdit = !!labor;
  const [editHours, editMinutes] = labor
    ? getHoursAndMinutesAndSeconds(labor.duration)
    : [0, 0];
  const fields: Array<IField> = [
    {
      name: 'assignedTo',
      type: 'select',
      label: t('assigned_to'),
      type2: 'user',
      midWidth: true
    },
    {
      name: 'hourlyRate',
      type: 'number',
      label: t('hourly_rate'),
      midWidth: true
    },
    {
      name: 'includeToTotalTime',
      type: 'switch',
      label: t('include_time'),
      helperText: t('include_time_description')
    },
    {
      name: 'startedAt',
      type: 'date',
      label: t('work_started_at')
    },
    {
      name: 'timeCategory',
      type: 'select',
      label: t('category'),
      type2: 'category',
      category: 'time-categories'
    },
    {
      name: 'duration',
      type: 'titleGroupField',
      label: t('duration')
    },
    {
      name: 'hours',
      type: 'number',
      label: t('hours'),
      midWidth: true,
      required: true
    },
    {
      name: 'minutes',
      type: 'number',
      label: t('minutes'),
      midWidth: true,
      required: true
    }
  ];
  const shape = {
    hours: Yup.number().required(t('required_hours')),
    minutes: Yup.number().required(t('required_minutes')),
    startedAt: Yup.date().required(t('required_field'))
  };
  const defaultValues = labor
    ? {
        ...labor,
        assignedTo: labor.assignedTo
          ? {
              label: `${labor.assignedTo.firstName} ${labor.assignedTo.lastName}`,
              value: labor.assignedTo.id
            }
          : null,
        timeCategory: labor.timeCategory
          ? { label: labor.timeCategory.name, value: labor.timeCategory.id }
          : null,
        hours: editHours,
        minutes: editMinutes
      }
    : { includeToTotalTime: true };
  return (
    <Dialog fullWidth maxWidth="sm" open={open} onClose={onClose}>
      <DialogTitle
        sx={{
          p: 3
        }}
      >
        <Typography variant="h4" gutterBottom>
          {isEdit ? t('edit_time') : t('add_time')}
        </Typography>
        <Typography variant="subtitle2">{t('add_time_description')}</Typography>
      </DialogTitle>
      <DialogContent
        dividers
        sx={{
          p: 3
        }}
      >
        {hasFeature(PlanFeature.ADDITIONAL_TIME) ? (
          <Form
            fields={fields}
            validation={Yup.object().shape(shape)}
            submitText={isEdit ? t('edit') : t('add')}
            values={defaultValues}
            enableReinitialize={isEdit}
            onChange={({ field, e }) => {}}
            onSubmit={async (values) => {
              const formattedValues = { ...values };
              formattedValues.assignedTo = formatSelect(
                formattedValues.assignedTo
              );
              formattedValues.timeCategory = formatSelect(
                formattedValues.timeCategory
              );
              formattedValues.duration =
                values.hours * 3600 + values.minutes * 60;
              if (isEdit) {
                return dispatch(
                  editLabor(labor.id, workOrderId, formattedValues as any)
                )
                  .catch((err) => showSnackBar(getErrorMessage(err), 'error'))
                  .then(() => onClose());
              } else
                return dispatch(createLabor(workOrderId, formattedValues))
                  .catch((err) => showSnackBar(getErrorMessage(err), 'error'))
                  .then(() => onClose());
            }}
          />
        ) : (
          <FeatureErrorMessage message="Upgrade to add Itemized time tracking to your Work Orders. " />
        )}
      </DialogContent>
    </Dialog>
  );
}
